  .split-heading { display: block; }
  .carousel-controls { margin-top: 18px; }
  .product-carousel { grid-auto-columns: 82%; }
  .seasonal-card.highlight { grid-row: auto; }
  .seasonal-card.highlight img { height: 230px; }
  .store-card { grid-template-columns: 1fr; gap: 8px; }
}
